 "Horas": "Horas",
 "<b style=\"font-size:25px;color:#8ea2ff\">Recomendación</b><br><span style=\"font-size:20px;color:#eceeff\">6-12 años: 9-12 h. 13-18 años: 8-10 h. Adultos: 7 h o más.</span>": "<b style=\"font-size:25px;color:#8ea2ff\">Recomendación</b><br><span style=\"font-size:20px;color:#eceeff\">6-12 anos: 9-12 h. 13-18 anos: 8-10 h. Adultos: 7 h ou máis.</span>",
 "<b style=\"font-size:25px;color:#ffd27d\">Fuente</b><br><span style=\"font-size:20px;color:#eceeff\">Academia Americana de Medicina del Sueño.</span>": "<b style=\"font-size:25px;color:#ffd27d\">Fonte</b><br><span style=\"font-size:20px;color:#eceeff\">Academia Americana de Medicina do Sono.</span>",
